package com.example.employeemanagement.service;
import com.example.employeemanagement.dto.DepartmentRequest; import com.example.employeemanagement.exception.*; import com.example.employeemanagement.model.Department; import com.example.employeemanagement.repository.DepartmentRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.*;
@Service @RequiredArgsConstructor public class DepartmentService {private final DepartmentRepository repo; public List<Department> all(){return repo.findAll();} public Department get(Long id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Department not found"));} public Department save(DepartmentRequest r){if(repo.existsByNameIgnoreCase(r.name()))throw new BadRequestException("Department already exists");return repo.save(Department.builder().name(r.name().trim()).build());} public Department update(Long id,DepartmentRequest r){Department d=get(id);d.setName(r.name().trim());return repo.save(d);} public void delete(Long id){repo.delete(get(id));}}
